<script setup>
import {Head,Link,useForm} from '@inertiajs/vue3';
const form=useForm({name:'',email:'',password:'',password_confirmation:''});
</script>
<template><Head title="Регистрация"/><main class="auth-page"><section class="auth-panel"><Link href="/" class="brand"><span class="brand-symbol">к<span>·</span></span><span>КОД<br><b>НОВОРОССИИ</b></span></Link><h1>Начните свою историю</h1><form @submit.prevent="form.post('/register')"><label>Ваше имя<input v-model="form.name" required maxlength="120" autocomplete="name"></label><label>Электронная почта<input v-model="form.email" type="email" required autocomplete="email"></label><label>Пароль от 8 символов<input v-model="form.password" type="password" required minlength="8" autocomplete="new-password"></label><label>Повторите пароль<input v-model="form.password_confirmation" type="password" required autocomplete="new-password"></label><p v-for="(error,key) in form.errors" :key="key" class="form-error">{{error}}</p><button class="primary" :disabled="form.processing">Создать аккаунт</button></form><p>Уже с нами? <Link href="/login">Войдите</Link></p></section></main></template>
